  "Object": { ca: "Objecte", es: "Objeto" },
  "Object has non-uniform scale, unwrap will operate on a non-scaled version of the mesh": { ca: "Object has non-uniform scale… L'objecte té una escala no uniforme: l'unwrap fa servir la malla sense escalar.", es: "Object has non-uniform scale… El objeto tiene una escala no uniforme: el unwrap usa la malla sin escalar." },
  "Unwrap could not solve {n} island(s), edge seams may need to be added": { ca: "Unwrap could not solve {n} island(s)… No s'han pogut resoldre {n} illa(es): cal afegir costures.", es: "Unwrap could not solve {n} island(s)… No se han podido resolver {n} isla(s): hay que añadir costuras." },
