  "Projected from view": { ca: "Projectada des de la vista", es: "Proyectada desde la vista" },
  "Put the mouse over a face and press L.": { ca: "Posa el ratolí sobre una cara i prem L.", es: "Pon el ratón sobre una cara y pulsa L." },
  "Put the mouse over an island in the UV Editor and press L.": { ca: "Posa el ratolí sobre una illa a l'UV Editor i prem L.", es: "Pon el ratón sobre una isla en el UV Editor y pulsa L." },
