  "STAGE {a} · STEP {b} OF {c}": { ca: "ETAPA {a} · PAS {b} DE {c}", es: "ETAPA {a} · PASO {b} DE {c}" },
  "Scale applied: the mesh keeps its shape and the scale is 1, 1, 1. Now unwrap again.": { ca: "Escala aplicada: la malla conserva la forma i l'escala és 1, 1, 1. Ara torna a desplegar.", es: "Escala aplicada: la malla conserva la forma y la escala es 1, 1, 1. Ahora vuelve a desplegar." },
  "Select Linked: the faces joined to it, up to the seams.": { ca: "Select Linked: les cares unides, fins a les costures.", es: "Select Linked: las caras unidas, hasta las costuras." },
  "Select UVs first: click an island in the UV Editor (A selects all).": { ca: "Primer selecciona UV: clica una illa a l'UV Editor (A ho selecciona tot).", es: "Primero selecciona UV: haz clic en una isla en el UV Editor (A lo selecciona todo)." },
  "Select the UVs first: mouse over the UV Editor and press A.": { ca: "Primer selecciona les UV: ratolí sobre l'UV Editor i prem A.", es: "Primero selecciona las UV: ratón sobre el UV Editor y pulsa A." },
  "Select the faces first (A selects all).": { ca: "Primer selecciona les cares (A ho selecciona tot).", es: "Primero selecciona las caras (A lo selecciona todo)." },
  "Select faces: Mark Seam cuts around them.": { ca: "Selecciona cares: Mark Seam talla al seu voltant.", es: "Selecciona caras: Mark Seam corta a su alrededor." },
